'use strict';

// Safe, widely-used utility. The application imports only this.
function get(object, path, defaultValue) {
  const keys = Array.isArray(path) ? path : String(path).split('.');
  let result = object;
  for (const key of keys) {
    if (result == null) return defaultValue;
    result = result[key];
  }
  return result === undefined ? defaultValue : result;
}

// SIMULATED CVE surface (prototype-pollution class, e.g. lodash
// CVE-2019-10744 / CVE-2018-3721): a deep-merge localized to ONE API. A
// crafted "__proto__" key mutates Object.prototype. The danger is confined to
// this function body; unlike a code-gen vuln it contains no eval/new Function,
// so it does not trip the global-hazard gate and CAN be proven unreachable and
// physically removed while `get` keeps working and `minilodash` stays present.
// Iterative (no self-reference) so the only reference is the export site.
function merge(target, source) {
  const stack = [[target, source]];
  while (stack.length) {
    const [dst, src] = stack.pop();
    for (const key in src) {
      if (src[key] && typeof src[key] === 'object') {
        if (!dst[key]) dst[key] = {};
        stack.push([dst[key], src[key]]); // no key filtering => pollutable
      } else {
        dst[key] = src[key];
      }
    }
  }
  return target;
}

module.exports.get = get;
module.exports.merge = merge;
